package unit1;

/*Write a Java program that uses long variables to store massive numbers representing
galactic distances and global web searches.*/



public class task25 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		long distanceToAndromedaKm = 2400000000000000000L; 

        // Global web searches: Estimated total Google searches per year worldwide
        long annualGlobalWebSearches = 2000000000000L; 

        // Print the values with descriptive text
        System.out.println("--- Galactic Distances ---");
        System.out.println("Distance to the Andromeda Galaxy: " + distanceToAndromedaKm + " km");

        System.out.println("\n--- Global Web Metrics ---");
        System.out.println("Estimated annual global web searches: " + annualGlobalWebSearches);
    

	}

}
